        Importance.LOW -> ImportanceColors(fg = Color(0xFF5B6475), bg = Color(0xFFEFECE5), rule = Color(0xFFB3B8C2))
        Importance.FYI -> ImportanceColors(fg = Color(0xFF5B6475), bg = Color(0xFFEFECE5), rule = Color(0xFFB3B8C2))
}

