        Importance.HIGH -> ImportanceColors(fg = Color(0xFFF3C06C), bg = Color(0xFF3A2C14), rule = Color(0xFFE8A33D))
        Importance.MEDIUM -> ImportanceColors(fg = Color(0xFFC3C9D4), bg = Color(0xFF252C3B), rule = Color(0xFF7D8596))
